import { initTRPC, inferRouterInputs, inferRouterOutputs } from '@trpc/server';
import { Overwrite } from '@trpc/server/core/internals/utils';
import { z } from 'zod';
import { expectTypeOf } from 'vitest';

type OldOverwrite<TType, TWith> = TType extends any
  ? TWith extends any
    ? {
        [K in keyof TType | keyof TWith]: K extends keyof TWith
          ? TWith[K]
          : K extends keyof TType
          ? TType[K]
          : never;
      }
    : never
  : never;

// primitive cases
expectTypeOf<Overwrite<string, string>>().toEqualTypeOf<string>();
// {} vs object
type E1 = {} extends object ? 1 : 0;
expectTypeOf<E1>().toEqualTypeOf<1>();

// any ctx
type AnyNew = Overwrite<any, {}>;
type AnyOld = OldOverwrite<any, {}>;
declare const anyNew: AnyNew;
declare const anyOld: AnyOld;
anyOld.foo; // old ok?
anyNew.foo; // new?

// unknown TWith
type UW = Overwrite<{ a: string }, unknown>;
expectTypeOf<UW>().toEqualTypeOf<{ a: string }>();

// array inputs + middleware
{
  const t = initTRPC.create();
  const r = t.router({
    arr: t.procedure
      .input(z.array(z.string()))
      .use((o) => o.next())
      .query(({ input }) => input),
    obj: t.procedure
      .input(z.object({ a: z.string() }))
      .use((o) => o.next())
      .input(z.object({ b: z.number() }))
      .query(({ input }) => input),
    optStr: t.procedure
      .input(z.string().optional())
      .use((o) => o.next())
      .query(({ input }) => input),
    date: t.procedure
      .input(z.date())
      .use((o) => o.next())
      .query(({ input }) => input),
  });
  type I = inferRouterInputs<typeof r>;
  type O = inferRouterOutputs<typeof r>;
  expectTypeOf<I['arr']>().toEqualTypeOf<string[]>();
  expectTypeOf<I['obj']>().toEqualTypeOf<{ a: string; b: number }>();
  expectTypeOf<I['optStr']>().toEqualTypeOf<string | undefined>();
  expectTypeOf<I['date']>().toEqualTypeOf<Date>();
  expectTypeOf<O['arr']>().toEqualTypeOf<string[]>();
}

// any context
{
  const t = initTRPC.context<any>().create();
  t.procedure
    .use((o) => o.next({ ctx: { user: 1 } }))
    .query(({ ctx }) => {
      ctx.foo;
      ctx.user;
    });
}
// unknown context? object context
{
  const t = initTRPC.context<{ a: number } | { b: string }>().create();
  t.procedure
    .use((o) => o.next({ ctx: { user: 1 } }))
    .query(({ ctx }) => {
      ctx.user;
    });
}

